import{_ as s,c as t,o as r,j as e,a as o}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"簡介","description":"帛書易 - 簡介","frontmatter":{"title":"簡介","description":"帛書易 - 簡介"},"headers":[],"relativePath":"classics/boshuyi/001.md","filePath":"classics/boshuyi/001.md"}'),i={name:"classics/boshuyi/001.md"};function c(n,a,l,d,p,m){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"簡介",tabindex:"-1"},[o("簡介 "),e("a",{class:"header-anchor",href:"#簡介","aria-label":"Permalink to “簡介”"},"​")],-1),e("p",null,"《帛書易》簡介 ​帛書《周易》1973年12月出土於湖南長沙馬王堆漢墓3號，與其它27種帛書一起出土。原盛於一漆盒內。關於帛書《周易》的抄錄年代，專家們的判斷是約在西漢文帝初年，即大約公元前180年至170年間。這意味著帛書《周易》的版本可能是基於更早的竹簡本進行抄錄的，其原始內容的撰寫時間應該更為久遠。相較於通行版本，帛書《周易》有其獨特之處。首先，其卦序與傳世本有所不同。其次，一些卦名也存在差異，這些差異可能源自通假字的使用。此外，帛書《周易》還包括了《易傳》部分，例如《二三子間》上下篇以及《繫辭》、《易之義》、《要》、《繆和》、《昭力》等篇章。內容與結構：帛書《周易》的內容主要分為“經”和“傳”兩部分。經部分主要是六十四卦的卦形符號與卦爻辭，包括陰爻和陽爻。這些卦形符號和卦爻辭是《周易》的核心，用於描述和解釋自然現象、人事變化以及道德準則。傳部分是對經文的闡釋和發揮，包括《彖傳》上下、《象傳》上下、《文言》、《繫辭傳》上下、《說卦傳》、《序卦傳》、《雜卦傳》共計7種10篇。這些傳文對於理解經文起到了重要的輔助作用，幫助讀者深入領會《周易》的哲學思想和智慧。編排與特點：帛書《周易》的編排經過精心考慮。它以經文在最前面，隨後分說經文，再通論大義，又於論說外記事，最後是傳《易》經師的言論。這種編排方式使得整部《周易》既有系統性，又有層次性，便於讀者閱讀和理解。此外，帛書《周易》以鍵、根、贛、辰、川、奪、羅、筭八個卦為基本卦，將六十四卦分為八組。每組中分別以固定的一卦為上卦，然後取與之相同的卦為下卦，組成一個六爻的卦。這種分組方式使得卦與卦之間的關係更加緊密，也更容易揭示其內在的邏輯和規律。文化價值：帛書《周易》的出土為我們提供了研究古代易學文化的重要資料。它不僅揭示了古代人們對宇宙、人生、精神、物質等問題的探求及演繹，也反映了古代社會的哲學思想和智慧。因此，帛書《周易》在學術研究和文化傳承方面都具有極高的價值。需要注意的是，儘管帛書《周易》與通行版本在某些方面存在差異，但這並不意味著通行版本不如出土版本真實可靠。兩者各有其特點和價值，我們應該以客觀、理性的態度對待它們，並結合其他相關資料進行綜合研究和分析。總的來說，帛書《周易》是一部珍貴的歷史文獻，它為我們瞭解古代易學文化提供了重要的線索和依據。通過深入研究帛書《周易》，我們可以更好地領略古代人們的智慧和哲學思想，也可以為現代社會的發展和進步提供有益的借鑑和啟示。",-1)])])}const h=s(i,[["render",c]]);export{f as __pageData,h as default};
